SELECT * FROM (SELECT CASE WHEN rating >= 3.9 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END AS rating_bucket, ROUND((100 * SUM(CASE WHEN country = 'DE' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_de, ROUND(AVG(rating), 2) AS avg_rating FROM suppliers WHERE city IN ('New York', 'Tokyo') GROUP BY CASE WHEN rating >= 3.9 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END) AS x WHERE pct_de >= 44
